const CIRCLE_FORM=import.meta.env.VITE_CIRCLE_FORM_EMBED_URL||'https://docs.google.com/forms/d/e/1FAIpQLSf-qz5my6XYer4uxyarq9Ot4UQxOvrTglGus26kX9r_D2SgRQ/viewform?embedded=true';
