function CirclePage(){
 const[activation,setActivation]=useState(false),[tier,setTier]=useState('The Collective'),[sent,setSent]=useState(false),[sending,setSending]=useState(false);
 const goPath=()=>document.getElementById('circle-pathways')?.scrollIntoView({behavior:'smooth',block:'start'});
 const openJoin=(name='The Collective')=>{setTier(name);setActivation(true)};
 const openWhatsApp=()=>{if(CIRCLE_WHATSAPP)window.open(CIRCLE_WHATSAPP,'_blank','noopener,noreferrer');else alert('Add VITE_CIRCLE_WHATSAPP_URL to your .env to activate the WOMATE Circle WhatsApp route.');};
 async function sendInquiry(e){e.preventDefault();const form=e.currentTarget;setSending(true);try{if(!CIRCLE_INQUIRY)throw new Error('missing');const data=Object.fromEntries(new FormData(form));const r=await fetch(CIRCLE_INQUIRY,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw new Error('request');setSent(true);form.reset()}catch(err){if(err.message==='missing') alert('Add VITE_CIRCLE_INQUIRY_ENDPOINT to your .env to activate direct inquiry delivery.');else alert('Your inquiry could not be sent. Please try again.')}finally{setSending(false)}}
 return <>
<section className="hero hero-circle"><div className="heroTop"><div className="heroCopy"><h1>A climate community for women.</h1><div className="actions"><button className="pill lime" onClick={()=>openJoin()}>Enter the Circle <ArrowUpRight size={16}/></button><button className="pill ghost" onClick={goPath}>Explore membership</button></div></div><HeroVisual type="circle"/></div></section>
<main className="circlePage">
<section className="circleIntro"><span>THE INNER RING OF CLIMATE LEADERSHIP</span><div><h2>Influence grows faster when women do not have to build alone.</h2><p>The WOMATE Circle is a specialised ecosystem for women architects of sustainability: a place to exchange intelligence, access opportunity, build professional visibility and turn peer connection into collective power.</p></div></section>
<section className="circlePromise"><div className="circleSectionHead"><span>FOSTERING VISIBILITY</span><h2>More than a network. A growth accelerator.</h2></div><div className="circlePromiseGrid"><article><b>01 · SHARED LEARNING</b><h3>Stay current together.</h3><p>Weekly capacity-building exchanges, resource sharing and peer intelligence for women navigating climate and sustainability work.</p></article><article><b>02 · DIRECT ACCESS</b><h3>See opportunity sooner.</h3><p>Curated fellowships, grants, projects and international speaking opportunities selected for women building credible climate careers.</p></article><article><b>03 · THE ANNUAL SIT</b><h3>Lead with intention.</h3><p>A strategic reflection and goal-setting space to review progress, sharpen direction and enter the next year deliberately.</p></article></div></section>
<section id="circle-pathways" className="circlePathways"><div className="circleSectionHead"><span>MEMBER PATHWAYS</span><h2>Choose the level of access that matches where you are going.</h2></div><div className="circleTierGrid">{circleTiers.map(([n,t,price,items],i)=><article className={'circleTier '+(i===1?'featured':'')} key={n}><div className="circleTierTop"><span>{n}</span><b>{i===0?'OPEN ACCESS':i===1?'PROFESSIONAL':'EXECUTIVE'}</b></div><h3>{t}</h3><div className="circlePrice">{price}</div><ul>{items.map(x=><li key={x}>{x}</li>)}</ul><button className={i===1?'pill darkbtn':'pill lime'} onClick={()=>openJoin(t)}>{i===0?'Join community':i===1?'Activate membership':'Enter the Vanguard'}</button></article>)}</div></section>
<section className="circlePath"><div className="circlePathCopy"><span>MEMBERSHIP ACTIVATION</span><h2>One clear route into the Circle.</h2><p>Complete your credentials first. Free members continue to community onboarding; Practitioner and Vanguard members complete the annual membership payment before WhatsApp admission.</p></div><div className="circleSteps"><div><b>01</b><strong>Complete credentials</strong><p>Tell WOMATE who you are, where you work and the climate space you are building in.</p></div><div><b>02</b><strong>Select your pathway</strong><p>Choose Collective, Practitioner or Vanguard based on the access you need.</p></div><div><b>03</b><strong>Secure membership</strong><p>Practitioner and Vanguard members complete annual payment through the configured secure payment route.</p></div><div><b>04</b><strong>Enter WhatsApp</strong><p>Continue to the Circle WhatsApp community for onboarding, opportunities, learning and peer connection.</p></div></div></section>
<section className="circleAccess"><div className="circleAccessCopy"><span>COMMUNITY ACCESS</span><h2>Already registered?</h2><p>Use the direct community route after completing your membership credentials and, where applicable, annual payment.</p></div><div className="circleAccessActions"><button className="pill lime" onClick={openWhatsApp}>Open WhatsApp community <ArrowUpRight size={16}/></button><a className="pill ghost" href={CIRCLE_PAYMENT} target="_blank" rel="noreferrer">Secure annual membership <ArrowUpRight size={16}/></a></div></section>
<section className="circleInquiry"><div><span>ASK WOMATE</span><h2>Not sure which pathway fits?</h2><p>Send a short note and the WOMATE team can guide you to the right Circle membership route.</p></div>{sent?<div className="circleSuccess"><ShieldCheck size={30}/><strong>Inquiry received.</strong><p>WOMATE can now follow up using the contact details you provided.</p></div>:<form onSubmit={sendInquiry}><input name="name" required placeholder="Full name"/><input name="email" required type="email" placeholder="Email address"/><input name="country" placeholder="Country"/><select name="pathway" defaultValue="Not sure"><option>Not sure</option><option>The Collective</option><option>The Practitioner</option><option>The Vanguard</option></select><textarea name="message" required placeholder="Tell us what you are looking for from the Circle."/><button className="pill darkbtn" disabled={sending}>{sending?'Sending…':'Send inquiry'} <ArrowUpRight size={16}/></button></form>}</section>
</main>
{activation&&<div className="circleModal" role="dialog" aria-modal="true"><button className="circleModalBackdrop" aria-label="Close membership activation" onClick={()=>setActivation(false)}/><div className="circleModalPanel"><div className="circleModalHead"><div><span>MEMBERSHIP ACTIVATION</span><h2>{tier}</h2></div><button aria-label="Close" onClick={()=>setActivation(false)}><X/></button></div><div className="circleModalBody"><div className="circleFormFrame"><iframe title="WOMATE Circle membership form" src={CIRCLE_FORM}>Loading…</iframe></div><aside><span>AFTER SUBMITTING</span><h3>Complete your route.</h3><p>{tier==='The Collective'?'The Collective is free. Submit your credentials, then continue directly to the community.':'Submit your credentials, complete annual membership payment, then continue to the WhatsApp community for onboarding.'}</p>{tier!=='The Collective'&&<a href={CIRCLE_PAYMENT} target="_blank" rel="noreferrer" className="pill lime">Proceed to secure payment <ArrowUpRight size={16}/></a>}<button onClick={openWhatsApp} className="pill darkbtn">{tier==='The Collective'?'Proceed to WhatsApp group':'Done & join community'} <ArrowUpRight size={16}/></button><small>Paid members should retain proof of successful payment for onboarding verification.</small></aside></div></div></div>}
</>}

